// Multiplayer sync runs on a timer, NOT the rAF loop — browsers pause rAF in
// background tabs, which would freeze our outgoing state and remote-player
// tracking the moment a player alt-tabs.
let lastNetT = performance.now();
setInterval(() => {
  const now = performance.now();
  const dt = Math.min((now - lastNetT) / 1000, 0.5);
  lastNetT = now;
  if (!(net && roomCode && game.player && game.mode === 'dm')) return;
  net.lerpStates(dt);
  game.remoteTargets = net.getRenderList().filter(r => r.hp > 0);
  netSendAccum += dt;
  if (netSendAccum > 1 / 15) {
    netSendAccum = 0;
    const p = game.player;
    net.sendState({
      x: p.pos[0], y: p.pos[1], z: p.pos[2],
      yaw: p.yaw, pitch: p.pitch, crouch: p.crouching,
      weapon: p.current, hp: p.hp,
    });
  }
}, 50);

// menu background needs a loaded map
renderer.loadMap(MAPS[selectedMap]);
